//! Runtime comparison with command-generated release validation evidence.

use blake2::{Blake2b, Digest, digest::consts::U32};
use serde_json::Value;

use crate::{RuntimeHandle, generated::network_pins};
use rtao_primitives::H256;

/// Compiled compatibility evidence generated by `cargo xtask compat`.
pub const COMPILED_COMPAT: &str = include_str!("../../../compat.json");

/// Whether e2e and interop evidence validate this exact runtime identity.
///
/// The connected chain is identified by its genesis hash, never by the
/// configured network label: labels such as `test` and an explicit endpoint
/// name the same chain that compatibility evidence records as `testnet`.
/// A metadata download alone supplies no validation range. An empty range or
/// missing exact runtime row therefore returns false.
pub fn runtime_validated(genesis: H256, runtime: &RuntimeHandle) -> bool {
    let Ok(document) = serde_json::from_str::<Value>(COMPILED_COMPAT) else {
        return false;
    };
    validated_by(&document, genesis, runtime)
}

/// Whether a genesis hash identifies a pinned public network.
///
/// Compatibility evidence can only ever cover these chains. Local and custom
/// development chains have their own genesis and are never validated.
pub fn pinned_public_genesis(genesis: H256) -> bool {
    let genesis = crate::hash_hex(genesis);
    [
        network_pins::FINNEY_GENESIS,
        network_pins::TEST_GENESIS,
        network_pins::DEVNET_GENESIS,
    ]
    .contains(&genesis.as_str())
}

/// Whether a genesis hash identifies Finney, the mainnet.
pub fn mainnet_genesis(genesis: H256) -> bool {
    crate::hash_hex(genesis) == network_pins::FINNEY_GENESIS
}

/// The validated runtime spec range compiled into this build, when present.
pub fn validated_spec_range() -> Option<(u64, u64)> {
    let document = serde_json::from_str::<Value>(COMPILED_COMPAT).ok()?;
    let range = document.get("validated_spec_range")?;
    Some((range.get("min")?.as_u64()?, range.get("max")?.as_u64()?))
}

fn validated_by(document: &Value, genesis: H256, runtime: &RuntimeHandle) -> bool {
    let Some(range) = document.get("validated_spec_range") else {
        return false;
    };
    let Some(min) = range.get("min").and_then(Value::as_u64) else {
        return false;
    };
    let Some(max) = range.get("max").and_then(Value::as_u64) else {
        return false;
    };
    let spec = u64::from(runtime.spec_version());
    if !(min..=max).contains(&spec) {
        return false;
    }
    let metadata_hash = format!(
        "0x{}",
        hex::encode(Blake2b::<U32>::digest(&runtime.core().metadata_bytes))
    );
    let genesis = crate::hash_hex(genesis);
    document
        .get("validated_runtimes")
        .and_then(Value::as_array)
        .is_some_and(|rows| {
            rows.iter().any(|row| {
                row.get("genesis").and_then(Value::as_str) == Some(genesis.as_str())
                    && row.get("spec_version").and_then(Value::as_u64) == Some(spec)
                    && row
                        .get("metadata_hash")
                        .and_then(|hash| hash.get("kind"))
                        .and_then(Value::as_str)
                        == Some("blake2b-256-raw")
                    && row
                        .get("metadata_hash")
                        .and_then(|hash| hash.get("value"))
                        .and_then(Value::as_str)
                        == Some(metadata_hash.as_str())
            })
        })
}

#[cfg(test)]
mod tests {
    #![allow(clippy::unwrap_used)]
    use super::*;
    use serde_json::json;

    #[test]
    fn range_requires_exact_runtime_identity_and_hash_algorithm() {
        let runtime = RuntimeHandle::parse(
            include_bytes!("../../../vendor/metadata/finney/478.v15.scale"),
            478,
            1,
            42,
        )
        .unwrap();
        let genesis = H256([7; 32]);
        let hash = format!(
            "0x{}",
            hex::encode(Blake2b::<U32>::digest(&runtime.core().metadata_bytes))
        );
        let mut evidence = json!({"validated_spec_range":{"min":477,"max":478},"validated_runtimes":[{"network":"finney","genesis":crate::hash_hex(genesis),"spec_version":478,"metadata_hash":{"kind":"blake2b-256-raw","value":hash}}]});
        assert!(validated_by(&evidence, genesis, &runtime));
        assert!(!validated_by(&evidence, H256([8; 32]), &runtime));
        evidence["validated_runtimes"][0]["spec_version"] = json!(477);
        assert!(!validated_by(&evidence, genesis, &runtime));
        evidence["validated_runtimes"][0]["spec_version"] = json!(478);
        evidence["validated_runtimes"][0]["metadata_hash"]["kind"] = json!("sha256");
        assert!(!validated_by(&evidence, genesis, &runtime));
        evidence["validated_spec_range"] = Value::Null;
        assert!(!validated_by(&evidence, genesis, &runtime));
    }

    fn genesis(text: &str) -> H256 {
        H256(
            hex::decode(text.trim_start_matches("0x"))
                .unwrap()
                .try_into()
                .unwrap(),
        )
    }

    // Matching is by genesis, so an evidence row's network label never
    // decides validation: the same runtime is refused under another genesis.
    #[test]
    fn evidence_row_matches_the_pinned_finney_runtime_by_genesis() {
        let runtime = RuntimeHandle::parse(
            include_bytes!("../../../vendor/metadata/finney/482.v15.scale"),
            482,
            1,
            42,
        )
        .unwrap();
        let finney = genesis(network_pins::FINNEY_GENESIS);
        let compiled: Value = serde_json::from_str(COMPILED_COMPAT).unwrap();
        let pin = compiled["metadata_pins"]
            .as_array()
            .unwrap()
            .iter()
            .find(|pin| pin["network"] == "finney" && pin["spec_version"] == 482)
            .unwrap();
        // The runtime's metadata hash is the hash `cargo xtask compat` records.
        let row = json!({"network":"finney","genesis":network_pins::FINNEY_GENESIS,"spec_version":482,"metadata_hash":pin["v15"]["metadata_hash"]});
        let evidence =
            json!({"validated_spec_range":{"min":482,"max":482},"validated_runtimes":[row]});
        assert!(validated_by(&evidence, finney, &runtime));
        assert!(!validated_by(
            &evidence,
            genesis(network_pins::TEST_GENESIS),
            &runtime
        ));
    }

    #[test]
    fn only_public_network_genesis_hashes_are_pinned() {
        for pinned in [
            network_pins::FINNEY_GENESIS,
            network_pins::TEST_GENESIS,
            network_pins::DEVNET_GENESIS,
        ] {
            assert!(pinned_public_genesis(genesis(pinned)));
        }
        assert!(!pinned_public_genesis(H256([7; 32])));
    }
}
